test("a retryable response is retried before success", async () => {
  const mock = await startMock([
    { status: 429, contentType: "application/json", body: JSON.stringify({ code: "rate_limited" }), headers: { "retry-after": "0" } },
    { status: 200, contentType: "application/json", body: "{\"data\":[]}" },
  ]);
  try {
    const client = new TypeshipClient({ baseUrl: mock.url, bearerToken: "test-token", maxRetries: 1, retry: { initialDelayMs: 0, maxDelayMs: 0 } });
    const result = await client.projects.list(undefined);
    assert.equal(result.ok, true, JSON.stringify(result));
    assert.equal(mock.requests.length, 2);
  } finally { mock.close(); }
});

test("a documented status maps to its generated error class", async () => {
  const mock = await startMock({ status: 400, contentType: "application/json", body: JSON.stringify({ code: "test_error", message: "expected failure", request_id: "req_test" }) });
  try {
    const client = new TypeshipClient({ baseUrl: mock.url, bearerToken: "test-token" });
    const result = await client.projects.list(undefined);
    assert.equal(result.ok, false, JSON.stringify(result));
    assert.equal(result.error.constructor.name, "BadRequestError");
    assert.equal(result.error.status, 400);
    assert.equal(result.error.response.requestId, "req_test");
  } finally { mock.close(); }
});

test("cursor pagination walks more than one page", async () => {
  const mock = await startMock([
    { status: 200, contentType: "application/json", body: "{\"data\":[{\"id\":\"item_1\"}],\"next_cursor\":\"cursor_test_2\",\"has_more\":true}" },
    { status: 200, contentType: "application/json", body: "{\"data\":[{\"id\":\"item_1\"}],\"next_cursor\":null,\"has_more\":false}" },
  ]);
  try {
    const client = new TypeshipClient({ baseUrl: mock.url, bearerToken: "test-token" });
    const items = [];
    for await (const item of client.projects.list(undefined)) items.push(item);
    assert.equal(items.length, 2);
    assert.equal(mock.requests.length, 2);
    assert.equal(new URL(mock.url + mock.requests[1].path).searchParams.get("cursor"), "cursor_test_2");
  } finally { mock.close(); }
});

